const today=(days=0)=>new Date(Date.now()+days*86400000).toISOString().slice(0,10);
// Current wall-clock time in a plant's zone, formatted for a datetime-local input.
const localAt=(iso,zone)=>{ const p=Object.fromEntries(new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).formatToParts(new Date(iso)).map(x=>[x.type,x.value])); return `${p.year}-${p.month}-${p.day}T${p.hour}:${p.minute}`; };
const localNow=zone=>localAt(Date.now(),zone);
// Imperial equivalents shown beside metric machine parameters for companies that work in imperial units.
const IMPERIAL={kN:[0.112404,'US tonf'],mm:[1/25.4,'in'],'cm³':[0.0610237,'in³'],L:[0.264172,'US gal'],'kg/h':[2.20462,'lb/h']};
const withUnits=(value,unit,units)=>{ if (value==null||value==='') return '—'; const base=`${formatNumber(value,2)}${unit?' '+unit:''}`; const imp=units==='imperial'&&IMPERIAL[unit]; return imp?`${base} <span class="muted">(${formatNumber(value*imp[0],1)} ${imp[1]})</span>`:base; };

const api=async(path,method='GET',body)=>{const r=await fetch('/api'+path,{method,headers:{'content-type':'application/json',...(state.token?{authorization:`Bearer ${state.token}`}:{})},body:body===undefined?undefined:JSON.stringify(body)});const data=await r.json();if(r.status===401&&state.token){state.token=null;state.user=null;clearSession();if(path!=='/me'&&path!=='/me/password')state.error=_t('ws.yourSessionHasEndedPlease');}if(!r.ok)throw Error(data.error||`${_t('ws.http',{status:r.status})}`);return data;};
const fail=e=>{ toast(e.message,'error'); if (!state.user) render(); };
async function load(){
  const paths=['dashboard','companies','plants','equipment','tickets','contracts','parts','providers','users','service-areas',...(manager()?['audit']:[]),...(deviceAdmin()?['devices']:[]),...(admin()?['integrations/status','alerts/emails']:[]),'alerts','alerts/summary','products',...(internal()?['settings/response-targets','settings/checklists']:[])];
  const out=await Promise.all(paths.map(async p=>[p,await api('/'+p).catch(()=>[])]));
  state.data=Object.fromEntries(out.map(([p,v])=>[{'integrations/status':'integrations','alerts/summary':'alertSummary','alerts/emails':'alertEmails','service-areas':'serviceAreas','settings/response-targets':'responseTargets','settings/checklists':'checklists'}[p]||p,v]));
  if (!state.cat) state.cat=await api('/catalog').catch(()=>null);
  state.floor=undefined; state.oee=undefined; state.oeeAi=undefined; state.condition=undefined; state.energy=undefined; ops.reset(); trace.reset();
  render();
}

// ---------- Sign-in ----------
// Sign-in session: kept for this browser tab (sessionStorage), or on this device when "Keep me signed in" is ticked
// (localStorage). Tokens expire after 8 hours and are cleared on sign-out or when the server rejects them.
const SESSION_KEY='pmp_session', EMAIL_KEY='pmp_last_email', REMEMBER_KEY='pmp_remember';
const storage={get:(area,key)=>{try{return window[area].getItem(key)}catch{return null}},set:(area,key,value)=>{try{window[area].setItem(key,value)}catch{}},remove:(area,key)=>{try{window[area].removeItem(key)}catch{}}};
function clearSession(){storage.remove('localStorage',SESSION_KEY);storage.remove('sessionStorage',SESSION_KEY);}
function saveSession(token,remember=storage.get('localStorage',SESSION_KEY)!=null){clearSession();storage.set(remember?'localStorage':'sessionStorage',SESSION_KEY,token);}
const storedSession=()=>storage.get('sessionStorage',SESSION_KEY)||storage.get('localStorage',SESSION_KEY);
const DEMO_EMAILS=['admin@demo.test','dispatch@demo.test','engineer@demo.test','acme@demo.test','maint@demo.test','nova@demo.test','atlas-admin@demo.test','atlas@demo.test','euro@demo.test'];
const DEMO_PASSWORD='DemoPass123!';
// "Viewing as" (demo copies only): each demo account by role and organisation.
const DEMO_ACCOUNTS=[['admin@demo.test','platform_admin',''],['dispatch@demo.test','dispatcher',''],['engineer@demo.test','engineer',''],['acme@demo.test','customer_admin','Acme'],['maint@demo.test','maintenance','Acme'],['nova@demo.test','customer_admin','Nova'],['atlas-admin@demo.test','provider_admin','Atlas'],['atlas@demo.test','provider_engineer','Atlas'],['euro@demo.test','provider_engineer','EuroTech']];
function loginView(){
  const lastEmail=state.loginEmail??storage.get('localStorage',EMAIL_KEY)??'', remember=storage.get('localStorage',REMEMBER_KEY)==='1';
  const demo=state.demoAccounts?`<div class="demo-accounts"><p class="muted">${_t('ws.demoAccountsOnThisCopy')} <code>${_t('ws.demopass123')}</code>${_t('ws.clickOneToFillIn')}</p>${DEMO_EMAILS.map(e=>`<button type="button" class="secondary demo-fill" data-email="${e}">${e.replace('@demo.test','')}</button>`).join('')}</div>`:'';
  $('#app').innerHTML=`<main class="login"><div class="brand">${_t('ws.mould')}<span>${_t('ws.care')}</span></div><h1>${_t('ws.serviceOperations')}</h1><p class="muted">${_t('ws.signInWithTheEmail')}</p><form id="login" novalidate><label for="login-email">${t('label.email')}</label><input id="login-email" name="email" type="email" required autocomplete="username" autocapitalize="none" autocorrect="off" spellcheck="false" inputmode="email" value="${esc(lastEmail)}"><label for="login-password">${t('label.password')}</label><div class="pw-row"><input id="login-password" name="password" type="password" required autocomplete="current-password"><button type="button" class="secondary" id="toggle-pw" aria-label="${_t('ws.showPassword')}">${_t('ws.show')}</button></div><label class="remember"><input type="checkbox" name="remember" ${remember?'checked':''}> ${_t('ws.keepMeSignedInOn')}</label><button id="login-submit">${t('action.signIn')}</button></form>${state.error?`<p class="notice error" role="alert">${esc(state.error)}</p>`:''}${demo}</main>`;
  const form=$('#login'), emailEl=$('#login-email'), pw=$('#login-password'), submitBtn=$('#login-submit');
  (lastEmail?pw:emailEl).focus();
  $('#toggle-pw').onclick=()=>{const show=pw.type==='password';pw.type=show?'text':'password';$('#toggle-pw').textContent=show?_t('ws.hide'):_t('ws.show');pw.focus();};
  document.querySelectorAll('.demo-fill').forEach(b=>b.onclick=()=>{emailEl.value=b.dataset.email;pw.value='DemoPass123!';submitBtn.focus();});
  form.onsubmit=async e=>{
    e.preventDefault();
    const f=new FormData(form), email=String(f.get('email')||'').trim(), password=String(f.get('password')||''), keep=f.get('remember')==='on';
    state.loginEmail=email;
    if(!email||!password){state.error=!email?_t('ws.enterYourEmailAddress'):_t('ws.enterYourPassword');return loginView();}
    submitBtn.disabled=true;submitBtn.textContent=_t('ws.signingIn');
    try{
      const r=await api('/auth/login','POST',{email,password});
      storage.set('localStorage',EMAIL_KEY,email);storage.set('localStorage',REMEMBER_KEY,keep?'1':'0');
      saveSession(r.token,keep);state.loginEmail=undefined;state.token=r.token;state.user=r.user;setLocale(r.user.preferences.locale);state.error='';
      if(r.user.mustChangePassword){state.page='account';toast(t('msg.mustChange'))}
      await load();
    }catch(err){state.error=err.message==='Failed to fetch'?_t('ws.cannotReachTheServerCheck'):err.message;loginView();}
  };
}
// Start: resume a saved session if the server still accepts it, otherwise show sign-in.
async function boot(){
  const token=storedSession();
  try{state.demoAccounts=(await api('/config')).demoAccounts}catch{state.demoAccounts=false}
  if(token){state.token=token;try{const me=await api('/me');state.user=me;setLocale(me.preferences.locale);if(me.mustChangePassword){state.page='account';toast(t('msg.mustChange'))}return await load();}catch{state.token=null;state.user=null;clearSession();state.error='';}}
  render();
}

