// Top bar across every page: environment, date; Viewing as (demo copies), the signed-in user, language, colour theme,
// Help, alerts and Sign out.
function topbar(){
  const theme=window.mcTheme?.get()||'light', a=state.data.alertSummary;
  const demoUser=state.demoAccounts&&DEMO_ACCOUNTS.some(([e])=>e===state.user.email);
  const env=state.demoAccounts?`<span class="env demo" title="${esc(t('env.demoHelp'))}">${esc(t('env.demo'))}</span>`:`<span class="env live" title="${esc(t('env.liveHelp'))}">${esc(t('env.live'))}</span>`;
  const viewAs=demoUser?`<label class="tb-field">${esc(t('label.viewingAs'))} <select id="view-as">${DEMO_ACCOUNTS.map(([e,role,org])=>`<option value="${e}" ${e===state.user.email?'selected':''}>${esc(label('role',role))}${org?` · ${esc(org)}`:''}</option>`).join('')}</select></label>`:'';
  const themes=['light','dark','auto'].map(k=>`<button type="button" data-theme-set="${k}" aria-pressed="${theme===k}">${{light:'☀ ',dark:'☾ ',auto:''}[k]}${esc(t('theme.'+k))}</button>`).join('');
  return `<header class="topbar"><div class="topbar-left">${env}<span class="muted tb-date">${formatDate(new Date().toISOString(),prefs().timezone)} · ${esc(prefs().timezone)}</span></div><div class="topbar-tools">${viewAs}`
    +`<span class="tb-user"><b>${esc(state.user.name)}</b><small>${esc(label('role',state.user.role))}</small></span>`
    +`<label class="tb-field" title="${esc(t('label.language'))}"><span class="sr-only">${esc(t('label.language'))}</span><select id="locale" aria-label="${esc(t('label.language'))}">${Object.entries(LOCALES).map(([k,v])=>`<option value="${k}" ${prefs().locale===k?'selected':''}>${v}</option>`).join('')}</select></label>`
    +`<div class="theme-switch" role="group" aria-label="${esc(t('theme.label'))}">${themes}</div>`
    +`<button type="button" class="bell" id="help-btn" aria-label="${helpLabel()}" title="${helpLabel()} (?)"><span aria-hidden="true">?</span> ${helpLabel()}</button>`
    +(factoryViewer()&&a?.critical!=null?`<button type="button" class="bell ${a.critical?'critical':a.warning?'warning':''}" data-nav-to="alerts" aria-label="${_t('ws.openAlertsCriticalWarning',{critical:a.critical,warning:a.warning})}"><span aria-hidden="true">🔔</span> ${a.critical+a.warning} ${a.critical?`<b>${_t('ws.critical',{critical:a.critical})}</b>`:''}</button>`:'')
    +`<a class="click signout" data-action="logout">${t('action.signOut')}</a></div></header>`;
}
// Viewing as: sign in as the chosen demo account and start fresh, so no page keeps the previous account's data.
async function viewAs(email){
  try { const r=await api('/auth/login','POST',{email,password:DEMO_PASSWORD}); saveSession(r.token); location.reload(); }
  catch (err) { toast(`${_t('ws.couldNotSwitchTo',{email:email,message:err.message})}`,'error'); render(); }
}
window.addEventListener('mc-theme',()=>{ if (state.user) render(); });
let lastShown='';
const pageIcon=()=>state.detail?.type==='ticket'?'tickets':state.detail?.type==='equipment'?'equipment':ICONS[state.page]?state.page:'dashboard';
// Menu groups can be folded; the choice is remembered in this browser. Opening a page inside a folded group unfolds it.
const NAV_KEY='mc-nav-closed';
let navShut=null;
function navClosed(){ if (!navShut) { try { navShut=new Set(JSON.parse(localStorage.getItem(NAV_KEY)||'[]')); } catch { navShut=new Set(); } } return navShut; }
function saveNav(){ try { localStorage.setItem(NAV_KEY,JSON.stringify([...navClosed()])); } catch {} }
const groupOf=page=>NAV_GROUPS.find(([title,pages])=>title&&pages.includes(page))?.[0];
let navPage=null;
function layout(content){
  if (state.page!==navPage) { navPage=state.page; const g=groupOf(state.page); if (g&&navClosed().delete(g)) saveNav(); }
  const nav=NAV_GROUPS.map(([title,pages],gi)=>{ const items=pages.filter(visible), shut=!!title&&navClosed().has(title); return items.length?`${title?`<button type="button" class="nav-group" data-nav-group="${esc(title)}" aria-expanded="${!shut}" aria-controls="ng-${gi}"><span>${esc(title)}</span><svg class="chev" viewBox="0 0 20 20" width="14" height="14" aria-hidden="true"><path d="M5 8l5 5 5-5" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg></button>`:_t('ws.text')}<div class="nav-items" id="ng-${gi}" ${shut?'hidden':''}>${items.map(p=>`<button class="nav ${state.page===p&&!state.detail?'active':''}" data-nav="${p}" ${state.page===p&&!state.detail?'aria-current="page"':''}>${icon(p)}<span>${esc(t('nav.'+p))}</span></button>`).join('')}</div>`:''; }).join('');
  const crumbs=state.detail?`<nav class="crumbs" aria-label="${_t('ws.breadcrumb')}"><a data-action="back">${esc(t('nav.'+state.page))}</a> › <span>${esc(state.detail.type==='ticket'?state.detail.value.title:assetName(state.detail.value.id)||state.detail.value.model)}</span></nav>`:'';
  // The menu keeps its own scroll position while the page is redrawn; a full browser reload starts it at the top.
  const menu=$('.side nav'), menuScroll=menu?[menu.scrollTop,menu.scrollLeft]:[0,0];
  $('#app').innerHTML=`<div class="shell"><aside class="side${state.menuOpen?' open':''}"><div class="brand">${_t('ws.mould')}<span>${_t('ws.care')}</span></div><button type="button" class="menu-btn" id="menu-btn" aria-expanded="${!!state.menuOpen}" aria-controls="main-nav"><svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true"><path d="M3 5h14M3 10h14M3 15h14" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"/></svg><span>${esc(t('nav.menu'))}</span></button><div class="brand-line">${esc(t('app.brandLine'))}</div><nav id="main-nav" aria-label="${_t('ws.main')}">${nav}</nav></aside><div class="workspace">${topbar()}<main class="main" id="main"><div class="top"><div class="title-block"><span class="page-icon" aria-hidden="true">${icon(pageIcon())}</span><div>${crumbs}<h1>${esc(state.detail?(state.detail.type==='ticket'?state.detail.value.title:`${state.detail.value.make} ${state.detail.value.model}`):t('nav.'+state.page))}</h1>${page.sub?`<p class="muted page-sub">${esc(page.sub)}</p>`:''}</div></div><div class="top-right">${page.actions?`<div class="page-actions">${page.actions}</div>`:''}</div></div>${state.error?`<div class="notice error" role="alert">${esc(state.error)}</div>`:''}${content}</main></div></div>`;
  const newMenu=$('.side nav'); if (newMenu) [newMenu.scrollTop,newMenu.scrollLeft]=menuScroll;
  document.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>{state.page=el.dataset.nav;state.detail=null;state.error='';state.menuOpen=false;render();$('#main')?.focus?.();});
  document.querySelectorAll('[data-nav-group]').forEach(el=>el.onclick=()=>{ const g=el.dataset.navGroup, shut=!navClosed().has(g); shut?navClosed().add(g):navClosed().delete(g); saveNav(); el.setAttribute('aria-expanded',String(!shut)); document.getElementById(el.getAttribute('aria-controls'))?.toggleAttribute('hidden',shut); });
  const menuBtn=$('#menu-btn'); if (menuBtn) menuBtn.onclick=()=>{ state.menuOpen=!state.menuOpen; $('.side').classList.toggle('open',state.menuOpen); menuBtn.setAttribute('aria-expanded',String(state.menuOpen)); };
  document.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>action(el.dataset.action,el.dataset.id));
  $('#locale').onchange=e=>api('/me','PATCH',{locale:e.target.value}).then(me=>{state.user=me;setLocale(me.preferences.locale);render()}).catch(fail);
  bindTables(render); bindCharts(); bindInlineForms(); ops.bind(); trace.bind(); vision.bind(); vision.startAlarms(); loadAuthImages(document,state.token); bindAssistant();
  document.querySelectorAll('[data-nav-to]').forEach(el=>el.onclick=()=>{state.page=el.dataset.navTo;state.detail=null;render()});
  $('#help-btn').onclick=showHelp;
  document.querySelectorAll('[data-theme-set]').forEach(b=>b.onclick=()=>window.mcTheme?.set(b.dataset.themeSet));
  const viewSel=$('#view-as'); if (viewSel) viewSel.onchange=()=>viewAs(viewSel.value);
  const shown=`${state.page}|${state.detail?.type||''}|${state.detail?.value?.id||''}`; if (shown!==lastShown) { lastShown=shown; window.scrollTo(0,0); }
  document.querySelectorAll('#main .empty').forEach(el=>{ if (!el.querySelector('.empty-icon')) el.insertAdjacentHTML('afterbegin',`<span class="empty-icon" aria-hidden="true">${icon(pageIcon())}</span>`); });
  const plantSel=$('#floor-plant'); if (plantSel) plantSel.onchange=()=>{state.floorPlant=plantSel.value;state.floor=undefined;render()};
  document.querySelectorAll('[data-energy]').forEach(el=>el.onchange=()=>{state.energyFilter[el.dataset.energy]=el.value;if(el.dataset.energy==='plantId')state.energyFilter.equipmentId='';state.energy=undefined;render()});
  document.querySelectorAll('[data-oee]').forEach(el=>el.onchange=()=>{state.oeeFilter[el.dataset.oee]=el.value;if(el.dataset.oee==='plantId')state.oeeFilter.equipmentId='';state.oee=undefined;render()});
}
// Help for the current page; the "?" key opens it too, unless the user is typing or a dialog is open.
function showHelp(){ openHelp(state.detail?.type==='ticket'?'ticket':state.detail?.type==='equipment'?'equipmentRecord':state.page,{groups:NAV_GROUPS,visible,title:p=>t('nav.'+p)}); }
document.addEventListener('keydown',e=>{ if (e.key!=='?'||!state.user||e.ctrlKey||e.metaKey||e.altKey||document.querySelector('dialog[open]')||e.target.closest('input,textarea,select,[contenteditable]')) return; e.preventDefault(); showHelp(); });
function render(){if(!state.user)return loginView();page={sub:'',actions:''};const content=state.detail?.type==='ticket'?ticketDetail():state.detail?.type==='equipment'?assetDetail():({dashboard:overview,tickets,equipment,contracts,parts,organisation,providers,settings:settingsView,integrations:integrationsView,audit:auditView,account,floor:floorView,oee:oeeView,condition:conditionView,energy:energyView,alerts:alertsView,products:productsView,...ops.views,...trace.views,...vision.views}[state.page]||overview)();layout(content);scheduleFloor();}
// Every page calls header() once: its description goes under the page title and its buttons to the top bar, so all
// pages share one header layout (icon, title, description; Help, alerts, date and page buttons on the right).
let page={sub:'',actions:''};
const header=(title,sub,actions='')=>{ page={sub,actions}; return ''; };

// ---------- Overview ----------
function overview(){
  const d=state.data.dashboard||{}, k=d.kpi||{}, tm=d.telemetry, list=(items,fn)=>items?.length?items.map(fn).join(''):`<p class="muted">${t('dash.none')}</p>`;
  const kpis=`<section class="kpis" aria-label="${_t('ws.keyFigures')}">${statTile(t('dash.open'),formatNumber(d.openTickets??0),{note:`${_t('ws.awaitingAssignment',{value:d.unassigned??0})}`})}${statTile(t('dash.breaches'),formatNumber(d.responseBreaches??0),{status:d.responseBreaches?'critical':'good',note:d.responseBreaches?_t('ws.needsAttention'):_t('ws.allOnTime')})}${statTile(_t('ws.mttrMeanTimeToRepair'),k.mttrHours==null?'—':`${formatNumber(k.mttrHours,1)} h`,{note:`${_t('ws.lastDays',{value:k.periodDays??90})}`})}${statTile(_t('ws.mtbfMeanTimeBetweenFailures'),k.mtbfHours==null?'—':`${formatNumber(k.mtbfHours)} h`,{note:`${_t('ws.breakdowns',{value:k.breakdowns??0})}`})}${statTile(_t('ws.availability'),k.availabilityPct==null?'—':`${formatNumber(k.availabilityPct,1)} %`,{note:_t('ws.calendarTimeBreakdownDowntime')})}${statTile(_t('ws.openSafetyIssues'),formatNumber(d.safetyOpen??0),{status:d.safetyOpen?'critical':'good',note:d.safetyOpen?_t('ws.treatAsCritical'):_t('ws.noneOpen')})}</section>`;
  const weekLabel=w=>new Intl.DateTimeFormat(prefs().locale,{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(w.weekStart));
  const charts=`<div class="chart-row">${columnChart('chart-weekly',{title:_t('ws.breakdownsPerWeek'),subtitle:_t('ws.last12WeeksByFailure'),valueLabel:_t('ws.breakdowns2'),points:(d.weekly||[]).map(w=>({value:w.breakdowns,label:weekLabel(w),tip:`${_t('ws.weekOf',{w:weekLabel(w)})}`})),xLabel:p=>p.label})}${barChart('chart-downtime',{title:_t('ws.downtimeByMachine'),subtitle:_t('ws.top5Last90Days'),valueLabel:_t('ws.downtime'),rows:(d.downtimeByAsset||[]).map(x=>({label:x.label,value:x.value})),formatValue:formatDuration})}</div>`;
  const iot=tm&&(customer()||dispatch())?`<section class="kpis small" aria-label="${_t('ws.machineData')}">${statTile(t('dash.reporting'),formatNumber(tm.current))}${statTile(t('dash.staleData'),formatNumber(tm.stale+tm.missing),{status:tm.stale+tm.missing?'warning':'',note:tm.stale+tm.missing?_t('ws.checkDevices'):''})}${statTile(t('dash.noDevice'),formatNumber(tm.unmapped))}${statTile(t('dash.alarms'),formatNumber(tm.activeAlarms),{status:tm.activeAlarms?'critical':'',note:tm.activeAlarms?_t('ws.activeNow'):''})}</section>`:'';
  return header(t('nav.dashboard'),_t('ws.openBreakdownsResponseTimesRepeat'))+`${kpis}${charts}${iot}<div class="detail"><div>
    <div class="panel"><h2>${t('dash.activeWork')}</h2>${simpleTable([t('nav.tickets'),t('label.priority'),t('label.status'),_t('ws.machineState')],(d.tickets||[]).map(tk=>`<tr><td><a data-action="ticket" data-id="${esc(tk.id)}">${esc(tk.title)}</a>${tk.safety_issue?_t('ws.safety'):''}<div class="muted">${esc(assetName(tk.equipment_id))}</div></td><td>${pill('priority',tk.priority)}</td><td>${pill('status',tk.status)}</td><td>${esc(tk.machine_state?humanise(tk.machine_state):'—')}</td></tr>`),_t('ws.noOpenWork'))}</div>
    <div class="panel"><h2>${t('dash.repeatFaults')}</h2>${list(d.repeatFaults,x=>`<div class="spread mini"><a data-action="equipment" data-id="${esc(x.equipmentId)}">${esc(x.label)}</a><b>${_t('ws.breakdowns',{value:x.value})}</b></div>`)}</div>
    ${d.incompleteAssets?.length?`<div class="panel"><h2>${_t('ws.recordsToComplete')}</h2><p class="muted">${_t('ws.theseMachinesWereRegisteredBefore')}</p>${d.incompleteAssets.map(a=>`<div class="spread mini"><a data-action="equipment" data-id="${esc(a.id)}">${esc(a.label)}</a><span class="muted">${esc(a.missing.slice(0,3).join(', '))}${a.missing.length>3?'…':''}</span></div>`).join('')}</div>`:''}
  </div><div>
    <div class="panel"><h2>${t('dash.responseByPriority')}</h2>${Object.entries(d.responseByPriority||{}).reverse().map(([p,m])=>`<div class="spread mini"><span>${_t('ws.open',{value:pill('priority',p),value2:d.byPriority?.[p]??0})}</span><b>${formatDuration(m)}</b></div>`).join('')}${d.breachedTickets?.length?`<h3>${t('dash.breaches')}</h3>${d.breachedTickets.map(x=>`<p class="mini">${pill('priority',x.priority)} <a data-action="ticket" data-id="${esc(x.id)}">${esc(x.title)}</a></p>`).join('')}`:''}</div>
    <div class="panel"><h2>${t('dash.upcoming')}</h2>${list(d.upcomingMaintenance,v=>`<p class="mini">${esc(v.asset_tag||'')} ${esc(v.make)} ${esc(v.model)}<br>${when(v.due_at,v.timezone)}</p>`)}${d.overdueVisits?.length?`<h3>${t('dash.overdue')}</h3>${d.overdueVisits.map(v=>`<p class="mini overdue">⚠ ${esc(v.make)} ${esc(v.model)}<br>${when(v.due_at,v.timezone)}</p>`).join('')}`:''}<h3>${_t('ws.contractRenewals')}</h3>${list(d.upcomingRenewals,c=>`<p class="mini">${esc(c.contract_number||'')} ${esc(c.title)}<br>${formatDate(c.renews_at)} ${c.noticeDue?_t('ws.noticePeriodStarted'):''}</p>`)}</div>
  </div></div>`;
}

// ---------- Lists ----------
function tickets(){
  const rows=state.data.tickets||[];
  return header(t('nav.tickets'),_t('ws.breakdownReportsAndServiceWork'),customer()||internal()?btn(t('action.raiseTicket'),'newTicket','primary'):'')+`<div class="panel">${dataTable('tickets',{rows,
    search:tk=>`${tk.title} ${tk.error_codes} ${assetName(tk.equipment_id)} ${tk.symptoms}`,
    filters:[{key:'status',label:t('label.status'),options:['open','assigned','accepted','in_progress','escalated','completed'].map(s=>[s,label('status',s)]),match:(r,v)=>r.status===v},{key:'priority',label:t('label.priority'),options:['critical','high','medium','low'].map(s=>[s,label('priority',s)]),match:(r,v)=>r.priority===v},{key:'category',label:_t('ws.failureCategory'),options:options(state.cat?.failureCategories||[]),match:(r,v)=>r.failure_category===v}],
    columns:[{title:t('nav.tickets'),cell:tk=>`<a data-action="ticket" data-id="${esc(tk.id)}">${esc(tk.title)}</a>${tk.safety_issue?_t('ws.safety'):''}<div class="muted">${esc(tk.error_codes||'')}${tk.failure_category?` · ${esc(humanise(tk.failure_category))}`:''}</div>`},{title:t('label.asset'),cell:tk=>esc(assetName(tk.equipment_id))},{title:t('label.priority'),cell:tk=>pill('priority',tk.priority)},{title:t('label.status'),cell:tk=>pill('status',tk.status)},{title:_t('ws.machineState'),cell:tk=>esc(tk.machine_state?humanise(tk.machine_state):'—')},{title:t('label.opened'),cell:tk=>when(tk.created_at,plantOf(tk.plant_id)?.timezone)},{title:t('label.assignment'),cell:tk=>esc(assigneeName(tk))}]})}</div>`;
}
