const HEALTH_LOOK={ok:['✓',lazyText('ws.healthy'),'good'],warning:['●',lazyText('ws.warning'),'warning'],critical:['⚠',lazyText('ws.critical2'),'critical'],unknown:['○',lazyText('ws.noData'),'neutral'],no_limit:['–',lazyText('ws.notMonitored'),'neutral'],no_data:['○',lazyText('ws.noData'),'neutral'],stale:['○',lazyText('ws.stale'),'neutral']};
const healthBadge=s=>{ const [i,l,tone]=HEALTH_LOOK[s]||HEALTH_LOOK.unknown; return `<span class="state ${tone}"><span aria-hidden="true">${i}</span> ${l}</span>`; };
const limitText=(l,unit)=>!l?'—':[l.warnLow!=null||l.warnHigh!=null?`${_t('ws.warn',{value:[l.warnLow!=null?'≤ '+formatNumber(l.warnLow,1):'',l.warnHigh!=null?'≥ '+formatNumber(l.warnHigh,1):''].filter(Boolean).join(' / ')})}`:'',l.critLow!=null||l.critHigh!=null?`${_t('ws.crit',{value:[l.critLow!=null?'≤ '+formatNumber(l.critLow,1):'',l.critHigh!=null?'≥ '+formatNumber(l.critHigh,1):''].filter(Boolean).join(' / ')})}`:''].filter(Boolean).join(' · ')+` ${unit}`;
async function loadCondition(){ [state.condition,state.conditionAi,state.mlPred,state.scrapAi]=await Promise.all([api('/factory/condition').catch(e=>{toast(e.message,'error');return []}),api('/factory/condition-insights').catch(()=>({})),api('/factory/ml-predictions').catch(()=>({})),api('/factory/scrap-insights').catch(()=>({}))]); }
const scrapLine=(sc,pr)=>{ const p=pr?.scrap, pc=p?Math.round(p.probability*100):null, tone=pc>=50?'critical':pc>=25?'warning':'good';
  if (sc?.status!=='elevated'&&!p) return ''; return `<p class="ml-line">${sc?.status==='elevated'?`<span class="state warning" title="${esc(sc.explanation)}">${_t('ws.scrapRising')} <b>${sc.recentPct} %</b> ${_t('ws.usual',{baselinePct:sc.baselinePct})}</span> `:''}${p?`<span class="state ${tone}" title="${_t('ws.modelHoldOutAuc',{value:esc(p.model.name+' '+p.model.version),value2:p.quality?.auc??'?'})}">${_t('ws.scrapSpikeRiskNextH',{horizonHours:p.horizonHours})} <b>${pc} %</b></span>`:''}${sc?.status==='elevated'?`<span class="muted">${esc(sc.explanation)}</span>`:''}</p>`; };
const mlLine=pr=>{ if (!pr||pr.status!=='ok'||(!pr.failure&&!pr.anomaly)) return ''; const f=pr.failure, a=pr.anomaly, tag=m=>`${m.name} ${m.version}`, pc=Math.round((f?.probability??0)*100), tone=pc>=50?'critical':pc>=25?'warning':'good';
  return `<p class="ml-line">${f?`<span class="state ${tone}" title="${_t('ws.modelHoldOutAuc2',{model:esc(tag(f.model)),value:f.quality?.auc??'?'})}">${_t('ws.breakdownRiskNextDays',{horizonDays:f.horizonDays})} <b>${pc} %</b></span> `:''}${a?`<span class="state ${a.level==='unusual'?'warning':'good'}" title="${_t('ws.modelScoreNormalAlertAbove',{model:esc(tag(a.model)),score:a.score,normalScore:a.normalScore,limit:a.limit})}">${_t('ws.overallPattern',{value:a.level==='unusual'?'unusual':'normal'})}</span>`:''} <span class="muted">${_t('ws.trainedModelVersionsOnHover')}</span></p>`; };
const AI_LOOK={normal:['✓',lazyText('ws.normal'),'good'],unusual:['●',lazyText('ws.unusual'),'warning'],degrading:['↗',lazyText('ws.degrading'),'warning'],learning:['○',lazyText('ws.learning'),'neutral']};
const aiBadge=i=>{ if (!i) return '<span class="muted">—</span>'; const [ic,l,tone]=AI_LOOK[i.status]||AI_LOOK.learning, eta=i.hoursToCritical!=null?`<div class="muted">${_t('ws.criticalIn',{value:i.hoursToCritical<48?i.hoursToCritical+' h':Math.round(i.hoursToCritical/24)+' days'})}</div>`:''; return `<span class="state ${tone}" title="${esc(i.explanation)}"><span aria-hidden="true">${ic}</span> ${l}</span>${eta}`; };
function conditionView(){
  if (!state.condition) { loadCondition().then(render); return `<div class="panel empty">${_t('ws.readingMachineCondition')}</div>`; }
  const list=state.condition, count=s=>list.filter(m=>m.status===s).length;
  const cards=list.map(m=>`<article class="panel health-card ${esc(m.status)}"><div class="spread"><div><b>${esc(m.assetTag||'—')}</b> <span class="muted">${esc(m.make)} ${esc(m.model)} · ${esc(m.plantName)}</span></div><span>${healthBadge(m.status)}${m.openAlerts?` <a class="pill critical" data-nav-to="alerts">${_t('ws.alert2',{openAlerts:m.openAlerts,value:m.openAlerts>1?'s':''})}</a>`:''}</span></div>
    ${simpleTable([_t('ws.parameter'),_t('ws.latest'),_t('ws.limits'),_t('ws.status'),_t('ws.aiBaseline')],m.parameters.map(p=>`<tr><td><a data-action="trend" data-id="${esc(m.id)}|${esc(p.parameter)}" title="${_t('ws.showTheTrend')}">${esc(p.label)}</a></td><td><b>${p.value==null?'—':`${formatNumber(p.value,1)} ${esc(p.unit)}`}</b>${p.observedAt?`<div class="muted">${_t('ws.ago',{observedAt:since(p.observedAt)})}</div>`:''}</td><td class="muted">${esc(limitText(p.limit,p.unit))}${p.limit&&!p.limit.autoTicket?_t('ws.noAutoTicket'):''}</td><td>${healthBadge(p.status)}</td><td>${aiBadge((state.conditionAi?.[m.id]||[]).find(i=>i.parameter===p.parameter))}</td></tr>`))}
    ${mlLine(state.mlPred?.[m.id])}${scrapLine(state.scrapAi?.[m.id],state.mlPred?.[m.id])}<div class="section-actions">${btn(_t('ws.explainWithAi'),'explain','secondary small',m.id)}${factoryManager(m.companyId)||dispatch()?btn(_t('ws.editAlarmLimits'),'limits','secondary small',m.id):''}<button type="button" class="link-btn" data-action="equipment" data-id="${esc(m.id)}">${_t('ws.machineRecord')}</button></div></article>`).join('');
  const explain=`<details class="panel explainer"><summary><b>${_t('ws.howConditionMonitoringWorks')}</b> <span class="muted">${_t('ws.aQuickGuide')}</span></summary><p>${_t('ws.sensorsReportSignalsThatChange')} <i>${_t('ws.before')}</i> ${_t('ws.aFailureOilHeatsUp')}</p><ul><li><b>${_t('ws.warning')}</b> ${_t('ws.planAnInspectionAnAlert')}</li><li><b>${_t('ws.aiBaseline')}</b> ${_t('ws.thePlatformAlsoLearnsWhat')} <i>${_t('ws.normalForEachMachine')}</i> ${_t('ws.whileItRunsTypicalLevel')} <b>${_t('ws.unusual')}</b>${_t('ws.andOneThatIsClimbing')} <b>${_t('ws.degrading')}</b> ${_t('ws.withAnEstimateOfThe')}<b>${_t('ws.learning')}</b> ${_t('ws.untilThen')}</li><li><b>${_t('ws.critical2')}</b> ${_t('ws.actNowTheAlertIs')} <b>${_t('ws.maintenanceTicketIsRaisedAutomatically')}</b> ${_t('ws.soItCanBeAssigned')}</li></ul><p>${_t('ws.vibrationLimitsFollowIso10816')}</p></details>`;
  return header(t('nav.condition'),_t('ws.machineHealthFromSensorReadings'))
    +`<section class="kpis small" aria-label="${_t('ws.machineHealth')}">${statTile(_t('ws.healthy'),formatNumber(count('ok')),{status:'good',note:_t('ws.allReadingsNormal')})}${statTile(_t('ws.warning'),formatNumber(count('warning')),{status:count('warning')?'warning':'',note:count('warning')?_t('ws.planAnInspection'):''})}${statTile(_t('ws.critical2'),formatNumber(count('critical')),{status:count('critical')?'critical':'',note:count('critical')?_t('ws.ticketRaised'):''})}${statTile(_t('ws.noDataNotMonitored'),formatNumber(count('unknown')))}</section>`
    +(list.length?`<div class="health-grid">${cards}</div>`:`<div class="panel empty">${_t('ws.noProductionMachinesYet')}</div>`)+explain;
}
async function trendDialog(equipmentId,parameter,hours=24){
  const tr=await api(`/factory/condition/${equipmentId}/trend?parameter=${encodeURIComponent(parameter)}&hours=${hours}`), zone=plantOf(assetOf(equipmentId)?.plant_id)?.timezone||prefs().timezone;
  const l=tr.limit||{}, limits=[l.warnHigh!=null&&{value:l.warnHigh,kind:'warning',label:`${_t('ws.warning2',{warnHigh:formatNumber(l.warnHigh,1)})}`},l.critHigh!=null&&{value:l.critHigh,kind:'critical',label:`${_t('ws.critical3',{critHigh:formatNumber(l.critHigh,1)})}`},l.warnLow!=null&&{value:l.warnLow,kind:'warning',label:`${_t('ws.warning3',{warnLow:formatNumber(l.warnLow,1)})}`},l.critLow!=null&&{value:l.critLow,kind:'critical',label:`${_t('ws.critical4',{critLow:formatNumber(l.critLow,1)})}`}].filter(Boolean);
  const fmtTime=iso=>new Intl.DateTimeFormat(prefs().locale,{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:zone}).format(new Date(iso));
  const d=openDialog(`${tr.label}: ${assetName(equipmentId)}`,`<div class="row" style="margin-bottom:10px">${[24,168].map(h=>`<button type="button" class="${h===hours?'primary':'secondary'} small" data-hours="${h}">${h===24?_t('ws.last24Hours'):_t('ws.last7DaysHourlyAverage')}</button>`).join('')}</div>${lineChart('chart-trend',{title:tr.label,subtitle:`${tr.unit} · ${hours===24?_t('ws.everyReading'):_t('ws.hourlyAverages')}`,points:tr.points,unit:tr.unit,limits,formatTime:fmtTime})}`);
  d.querySelectorAll('[data-hours]').forEach(b=>b.onclick=()=>trendDialog(equipmentId,parameter,Number(b.dataset.hours)));
  bindCharts();
}
