async function loadEnergy(){ const f=state.energyFilter||(state.energyFilter={range:'7d',plantId:'',equipmentId:''}); const q=new URLSearchParams({from:new Date(RANGES[f.range][1]()).toISOString(),to:new Date().toISOString(),...(f.plantId?{plantId:f.plantId}:{}),...(f.equipmentId?{equipmentId:f.equipmentId}:{})}); state.energy=await api('/factory/energy?'+q).catch(e=>{toast(e.message,'error');return null}); }
function energyView(){
  if (state.energy===undefined) { loadEnergy().then(render); return `<div class="panel empty">${_t('ws.addingUpEnergyUse')}</div>`; }
  const f=state.energyFilter, en=state.energy||{total:{},machines:[],daily:[]}, tot=en.total;
  const machines=(state.data.equipment||[]).filter(e=>(state.cat?.productionMachines||[]).includes(e.machine_type)&&(!f.plantId||e.plant_id===f.plantId));
  const filters=`<div class="table-tools"><select data-energy="range" class="tt-filter" aria-label="${_t('ws.period')}">${Object.entries(RANGES).map(([k,[l]])=>`<option value="${k}" ${f.range===k?'selected':''}>${l}</option>`).join('')}</select><select data-energy="plantId" class="tt-filter" aria-label="${_t('ws.plant')}"><option value="">${_t('ws.allPlants')}</option>${(state.data.plants||[]).map(p=>`<option value="${esc(p.id)}" ${f.plantId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select><select data-energy="equipmentId" class="tt-filter" aria-label="${_t('ws.machine')}"><option value="">${_t('ws.allMachines')}</option>${machines.map(e=>`<option value="${esc(e.id)}" ${f.equipmentId===e.id?'selected':''}>${esc(e.asset_tag||'')} ${esc(e.make)} ${esc(e.model)}</option>`).join('')}</select></div>`;
  const tiles=`<section class="kpis" aria-label="${_t('ws.energy')}">${statTile(_t('ws.energyUsed'),`${t('ws.kwh',{kwh:formatNumber(tot.kwh,0)})}`)}${statTile(_t('ws.energyPerKg'),tot.secKwhPerKg==null?'—':`${_t('ws.kwhKg',{secKwhPerKg:formatNumber(tot.secKwhPerKg,2)})}`,{note:_t('ws.specificEnergyConsumption')})}${statTile(_t('ws.wastedEnergy'),tot.wastePct==null?'—':`${formatNumber(tot.wastePct,1)} %`,tot.wastePct>15?{status:'warning',note:`${_t('ws.kwhWhileNotProducing',{wasteKwh:formatNumber(tot.wasteKwh,0)})}`}:{note:`${_t('ws.kwhWhileNotProducing2',{value:formatNumber(tot.wasteKwh??0,0)})}`})}${statTile('CO₂',tot.co2Kg==null?'—':`${formatNumber(tot.co2Kg/1000,2)} t`,{note:_t('ws.fromTheGridEmissionFactor')})}${statTile(_t('ws.cost'),tot.cost==null?'—':formatMoney(Math.round(tot.cost*100),tot.currency),{note:tot.cost==null?_t('ws.setTheEnergyPriceUnder'):''})}${statTile(_t('ws.peakPower'),tot.peakKw==null?'—':`${formatNumber(tot.peakKw,0)} kW`,{note:_t('ws.highestSingleMachine')})}</section>`;
  const dayLabel=d=>new Intl.DateTimeFormat(prefs().locale,{day:'numeric',month:'short',timeZone:'UTC'}).format(new Date(d+'T00:00:00Z'));
  const charts=`<div class="chart-row">${columnChart('chart-kwh-daily',{title:_t('ws.energyPerDay'),subtitle:_t('ws.kwhAllSelectedMachines'),valueLabel:'kWh',points:(en.daily||[]).map(d=>({value:d.kwh,label:dayLabel(d.date),tip:dayLabel(d.date)})),formatValue:v=>`${_t('ws.kwh2',{v:formatNumber(v,0)})}`})}${barChart('chart-kwh-machine',{title:_t('ws.energyByMachine'),subtitle:_t('ws.biggestUsersFirst'),valueLabel:_t('ws.energy'),rows:[...(en.machines||[])].sort((a,b)=>b.kwh-a.kwh).filter(m=>m.kwh>0).map(m=>({label:`${m.assetTag||''} ${m.name}`,value:Math.round(m.kwh)})),formatValue:v=>`${_t('ws.kwh2',{v:formatNumber(v,0)})}`})}</div>`;
  const table=`<div class="panel"><h2>${_t('ws.byMachine')}</h2>${simpleTable([_t('ws.machine'),_t('ws.energy'),_t('ws.output'),_t('ws.kwhPerKg'),_t('ws.wasted'),_t('ws.peak'),_t('ws.co')],(en.machines||[]).map(m=>`<tr><td><a data-action="equipment" data-id="${esc(m.equipmentId)}">${esc(m.assetTag||'')}</a> <span class="muted">${esc(m.name)}</span></td><td>${_t('ws.kwh',{kwh:formatNumber(m.kwh,0)})}</td><td>${m.kg?`${formatNumber(m.kg,0)} kg`:'—'}</td><td><b>${m.secKwhPerKg==null?'—':formatNumber(m.secKwhPerKg,2)}</b></td><td>${m.kwh?`${formatNumber(m.wasteKwh/m.kwh*100,1)} %`:'—'}</td><td>${m.peakKw==null?'—':`${formatNumber(m.peakKw,0)} kW`}</td><td>${_t('ws.kg',{co2Kg:formatNumber(m.co2Kg,0)})}</td></tr>`),_t('ws.noProductionMachinesInThis'))}</div>`;
  const explain=`<details class="panel explainer"><summary><b>${_t('ws.readingTheEnergyFigures')}</b> <span class="muted">${_t('ws.aQuickGuide')}</span></summary><ul><li><b>${_t('ws.energyPerKg')}</b> ${_t('ws.specificEnergyConsumptionIsThe')}</li><li><b>${_t('ws.wastedEnergy')}</b> ${_t('ws.isUsedWhileAMachine')}</li><li><b>${_t('ws.co')}</b> ${_t('ws.kwhGridEmissionFactorEnter')}</li><li><b>${_t('ws.peakPower')}</b> ${_t('ws.drivesDemandChargesOnMany')}</li></ul></details>`;
  return header(t('nav.energy'),_t('ws.electricityUseEnergyPerKg'))+filters+tiles+charts+table+explain;
}

