function bindAssistant(){
  const chat=document.getElementById('chat'); if (chat) chat.scrollTop=chat.scrollHeight;
  const f=document.getElementById('ai-form'); if (!f) return;
  const pick=f.photo, note=document.getElementById('photo-name');
  pick.onchange=()=>{ const file=pick.files[0]; note.hidden=!file; note.textContent=file?`${_t('ws.willBeSentWithYour',{name:file.name,value:file.size>5*1024*1024?_t('ws.tooLargeMax5Mb'):''})}`:''; };
  document.querySelectorAll('[data-ask]').forEach(c=>c.onclick=()=>{ f.message.value=c.dataset.ask; f.requestSubmit(); });
  f.onsubmit=async e=>{ e.preventDefault(); const message=f.message.value.trim(), file=pick.files[0], b=f.querySelector('button.primary');
    if (!message&&!file) { f.message.focus(); return toast(_t('ws.typeAQuestionOrAdd'),'error'); }
    if (file?.size>5*1024*1024) return toast(_t('ws.thePhotoIsLargerThan'),'error');
    b.disabled=true; b.textContent=_t('ws.thinking'); f.message.readOnly=true;
    const preview=file?`<img class="chat-photo" src="${URL.createObjectURL(file)}" alt="">`:'';
    chat?.insertAdjacentHTML('beforeend',`<div class="msg user"><div class="who">${esc(state.user.name)}</div>${preview}<p>${esc(message||_t('ws.whatDoYouSeeIn'))}</p></div><div class="msg assistant pending"><p class="muted">${_t('ws.theAssistantIsWorkingOn')}</p></div>`); if (chat) chat.scrollTop=chat.scrollHeight;
    try { const tk=state.detail.value, photo=file?{filename:file.name,mime:file.type,base64:await fileBase64(file)}:undefined;
      const r=await api(`/tickets/${tk.id}/assistant`,'POST',{message,...(photo?{photo}:{})});
      if (state.detail?.value?.id===tk.id) { state.detail.value=await loadDetail('ticket',tk.id); state.detail.value.assistantData=r; render(); document.getElementById('ai-form')?.message.focus(); } }
    catch (err) { toast(err.message,'error'); chat?.querySelectorAll('.msg').forEach((m,i,all)=>{ if (i>=all.length-2) m.remove(); }); b.disabled=false; b.textContent=_t('ws.ask'); f.message.readOnly=false; } };
  f.message.onkeydown=e=>{ if (e.key==='Enter'&&(e.ctrlKey||e.metaKey)) f.requestSubmit(); };
}
async function openVr(tk){
  const a=tk.asset||{}, g=tk.guideData?.guide; if (!g) return;
  const image=imageSrc(a)?await authImageUrl(imageSrc(a),state.token):null;
  const { openVrGuide }=await import('./shared/vr.js');
  await openVrGuide({title:tk.title,critical:tk.priority==='critical',guide:g,image,
    machine:{name:`${a.asset_tag?a.asset_tag+' · ':''}${a.make||''} ${a.model||''}`,detail:`${tk.plant?.name||''} · ${a.location||''} · SN ${a.serial_number||''}`,report:`${tk.symptoms}${tk.error_codes?`${_t('ws.codes',{error_codes:tk.error_codes})}`:''}${tk.safety_issue?'\n⚠ Safety issue reported':''}`}});
}

