function plantForm(p){
  const body=section(_t('ws.plant'),`${p?'':select('companyId',_t('ws.company'),(state.data.companies||[]).map(c=>[c.id,c.name]),{required:true})}${field('name',_t('ws.plantName'),{value:p?.name,required:true})}${field('address',_t('ws.address'),{value:p?.address,required:true,wide:true})}${field('country',_t('ws.country'),{value:p?.country,required:true,maxlength:2,help:_t('ws.twoLetterIsoCode')})}${select('serviceArea',_t('ws.serviceArea'),sa(),{value:p?.service_area,required:true,help:_t('ws.engineersAndServiceProvidersCovering')})}${select('operatingPattern',_t('ws.operatingPattern'),options(state.cat?.operatingPatterns||[]),{value:p?.operating_pattern||'24x7',required:true})}${zoneSelect('timezone',_t('ws.timeZone'),p?.timezone||'')}`);
  openDialog(p?`${t('action.edit')}: ${p.name}`:_t('ws.addPlant'),body,{onSubmit:async fd=>{ const v=Object.fromEntries(fd); await save(p?'/plants/'+p.id:'/plants',p?'PATCH':'POST',{...v,country:v.country.toUpperCase()},p?_t('ws.plantUpdated'):_t('ws.plantAdded')); }});
}
function userForm(){
  const roles=is('provider_admin')?['provider_engineer']:admin()?['customer_admin','plant_manager','maintenance','dispatcher','engineer','provider_admin','provider_engineer']:['plant_manager','maintenance'];
  const org=is('provider_admin')?select('providerId',_t('ws.provider'),(state.data.providers||[]).map(p=>[p.id,p.name]),{required:true,value:state.user.providerId}):`${select('companyId',_t('ws.companyCustomerRoles'),(state.data.companies||[]).map(c=>[c.id,c.name]),{value:is('customer_admin')?state.user.companyId:''})}${admin()?select('providerId',_t('ws.serviceProviderForServiceProvider'),(state.data.providers||[]).map(p=>[p.id,p.name])):''}`;
  const body=section(_t('ws.account'),`${select('role',_t('ws.role'),roles.map(x=>[x,label('role',x)]),{required:true})}${org}${field('name',_t('ws.fullName'),{required:true})}${field('jobTitle',_t('ws.jobTitle'))}${field('email',t('label.email'),{type:'email',required:true})}${field('phone',_t('ws.phone'),{type:'tel',help:_t('ws.requiredForFieldEngineers')})}${field('password',_t('ws.temporaryPassword'),{type:'text',required:true,minlength:12,autocomplete:'off',help:_t('ws.atLeast12CharactersThey')})}`)
    +(admin()||is('provider_admin')?`<div id="field-extra">${section(_t('ws.fieldService'),`${areaChecks('serviceAreas',[],false)}${machineChecks('skills',[],false)}`,_t('ws.requiredForEngineersUsedTo'))}</div>`:'');
  openDialog(_t('ws.addUser'),body,{onOpen:d=>{ const role=d.querySelector('[name=role]'); const sync=()=>{ const fieldRole=(state.cat?.fieldRoles||[]).includes(role.value); d.querySelector('[name=phone]').required=fieldRole; const extra=d.querySelector('#field-extra'); if (extra) { extra.hidden=!['engineer','provider_engineer','provider_admin'].includes(role.value); extra.querySelectorAll('[data-required-group-x],fieldset.checks').forEach(fs=>{ if (fieldRole) fs.setAttribute('data-required-group',fs.querySelector('input').name); else fs.removeAttribute('data-required-group'); }); } }; role.onchange=sync; sync(); },
    onSubmit:async fd=>{ const v=Object.fromEntries(fd), body={...v,serviceAreas:fd.getAll('serviceAreas'),skills:fd.getAll('skills')};
      if (['provider_admin','provider_engineer'].includes(v.role)) delete body.companyId; else delete body.providerId; if (['dispatcher','engineer'].includes(v.role)) delete body.companyId; if (!v.phone) delete body.phone;
      await save('/users','POST',body,_t('ws.userAddedShareTheTemporary')); }});
}
// Edit a user's details. Role, company and email stay as created; deactivate and re-add to change them.
function userEditForm(x){
  const fieldWork=['engineer','provider_engineer','provider_admin'].includes(x.role), fieldRole=(state.cat?.fieldRoles||[]).includes(x.role);
  const body=section(_t('ws.account'),`${field('name',_t('ws.fullName'),{value:x.name,required:true})}${field('jobTitle',_t('ws.jobTitle'),{value:x.job_title||''})}${field('phone',_t('ws.phone'),{type:'tel',value:x.phone||'',required:fieldRole,help:fieldRole?_t('ws.requiredForFieldEngineers'):''})}<p class="muted wide">${esc(label('role',x.role))} · ${esc(x.email)}</p>`)
    +(fieldWork?section(_t('ws.fieldService'),`${areaChecks('serviceAreas',parseList(x.service_areas),fieldRole)}${machineChecks('skills',parseList(x.skills),fieldRole)}`,_t('ws.usedToMatchThemTo')):'');
  openDialog(`${t('action.edit')}: ${x.name}`,body,{onSubmit:async fd=>{ const v=Object.fromEntries(fd), body={name:v.name,jobTitle:v.jobTitle,phone:v.phone};
    if (fieldWork) Object.assign(body,{serviceAreas:fd.getAll('serviceAreas'),skills:fd.getAll('skills')});
    await save('/users/'+x.id,'PATCH',body,_t('ws.userUpdated')); }});
}
// Reschedule a visit, change its scope, or cancel it. Times are the machine's plant local time.
function visitForm(c,v){
  const zone=plantOf(assetOf(v.equipment_id)?.plant_id)?.timezone||'UTC';
  const body=`<div class="form-grid"><p class="muted wide">${esc(c.contract_number||c.title)} · ${when(v.due_at,zone)}</p>${field('dueAt',_t('ws.dateAndTimePlantLocal'),{type:'datetime-local',value:localAt(v.due_at,zone),required:true})}${select('status',t('label.status'),['scheduled','completed','cancelled'].map(x=>[x,label('status',x)]),{value:v.status,required:true})}${field('notes',_t('ws.scopeOfVisit'),{value:v.notes||'',wide:true})}</div>`;
  openDialog(`${t('action.edit')}: ${assetName(v.equipment_id)}`,body,{onSubmit:async fd=>{ const f=Object.fromEntries(fd), patch={status:f.status,notes:f.notes};
    if (f.dueAt!==localAt(v.due_at,zone)) patch.dueAt=f.dueAt;
    await save('/visits/'+v.id,'PATCH',patch,f.status==='cancelled'?_t('ws.visitCancelled'):_t('ws.visitUpdated')); }});
}
// Move a device to another machine of the same company, or change when its data counts as stale.
function deviceForm(x){
  const machines=(state.data.equipment||[]).filter(e=>e.company_id===x.company_id).map(e=>[e.id,assetName(e.id)]);
  const body=`<div class="form-grid">${select('equipmentId',t('label.asset'),machines,{value:x.equipment_id,required:true,help:_t('ws.readingsFromNowOnAre')})}${field('staleAfterMinutes',_t('ws.markStaleAfter'),{type:'number',value:x.stale_after_minutes,unit:'min',min:1,max:10080,required:true})}</div>`;
  openDialog(`${t('action.edit')}: ${x.external_device_id}`,body,{onSubmit:async fd=>{ await save('/devices/'+x.id,'PATCH',{equipmentId:fd.get('equipmentId'),staleAfterMinutes:Number(fd.get('staleAfterMinutes'))},_t('ws.deviceUpdated')); }});
}
function providerForm(p){
  const body=section(_t('ws.provider'),`${field('name',_t('ws.companyName'),{value:p?.name,required:true,wide:true})}${field('country',_t('ws.country'),{value:p?.country,required:true,maxlength:2,help:_t('ws.twoLetterIsoCode')})}${field('certifications',_t('ws.certifications'),{value:p?.certifications,help:_t('ws.eGIso9001Oem')})}`)
    +section(_t('ws.contact'),`${field('contactName',_t('ws.name'),{value:p?.contact_name,required:true})}${field('contactEmail',_t('ws.email'),{type:'email',value:p?.contact_email,required:true})}${field('contactPhone',_t('ws.phone'),{type:'tel',value:p?.contact_phone,required:true})}`)
    +section(_t('ws.qualification'),`${field('insuranceExpiry',_t('ws.liabilityInsuranceValidUntil'),{type:'date',value:p?.insurance_expiry?.slice(0,10),help:_t('ws.neededBeforeApproval')})}${areaChecks('serviceAreas',parseList(p?.service_areas),true)}${machineChecks('skills',parseList(p?.skills),true)}`);
  openDialog(p?`${t('action.edit')}: ${p.name}`:_t('ws.addProvider'),body,{onSubmit:async fd=>{ const v=Object.fromEntries(fd); await save(p?'/providers/'+p.id:'/providers',p?'PATCH':'POST',{...v,country:v.country.toUpperCase(),insuranceExpiry:v.insuranceExpiry||null,serviceAreas:fd.getAll('serviceAreas'),skills:fd.getAll('skills')},p?_t('ws.serviceProviderUpdated'):_t('ws.serviceProviderAddedNotYet')); }});
}
// Edit a contract: everything except the customer. Scheduled visits keep the period and covered machines in check.
function renewalForm(c){
  const machines=(state.data.equipment||[]).filter(e=>e.company_id===c.company_id).map(e=>[e.id,assetName(e.id)]);
  const body=section(_t('ws.contract'),`${field('contractNumber',_t('ws.contractNumber'),{value:c.contract_number,required:true})}${field('title',_t('ws.title'),{value:c.title,required:true,wide:true})}${field('startsAt',t('label.starts'),{type:'date',value:c.starts_at.slice(0,10),required:true})}${field('renewsAt',_t('ws.endsRenews'),{type:'date',value:c.renews_at.slice(0,10),required:true})}${field('noticeDays',_t('ws.renewalNoticePeriod'),{type:'number',value:c.notice_days,required:true,unit:'days',min:0,max:365})}${select('status',t('label.status'),['active','expired','cancelled'].map(x=>[x,label('status',x)]),{value:c.status,required:true})}`)
    +section(_t('ws.serviceLevels'),`${select('coverageHours',_t('ws.coverageHours'),options(state.cat?.coverageHours||[]),{value:c.coverage_hours,required:true})}${field('responseHours',_t('ws.responseTarget'),{type:'number',value:c.response_hours,required:true,unit:'hours',min:1,max:720})}${field('restoreHours',_t('ws.restoreTarget'),{type:'number',value:c.restore_hours??'',unit:'hours',min:1,max:720})}${field('visitsPerYear',_t('ws.preventiveVisitsPerYear'),{type:'number',value:c.visits_per_year,required:true,min:0,max:52})}`)
    +section(_t('ws.scope'),`<div class="wide">${checkboxes('equipmentIds',_t('ws.coveredMachines'),machines,{values:c.equipmentIds,required:true,help:_t('ws.aMachineWithScheduledVisits')})}</div>${field('commitments',t('label.commitments'),{type:'textarea',value:c.commitments,required:true,wide:true})}${field('exclusions',t('label.exclusions'),{type:'textarea',value:c.exclusions,required:true,wide:true})}`);
  openDialog(`${t('action.edit')}: ${c.contract_number||c.title}`,body,{onSubmit:async fd=>{ const v={...Object.fromEntries(fd),equipmentIds:fd.getAll('equipmentIds')}; if (v.status==='cancelled'&&c.status!=='cancelled'&&!await confirmAction(_t('ws.cancelThisContract'),_t('ws.machinesItCoversWillFall'),{confirmLabel:_t('ws.cancelContract')})) throw Error(_t('ws.notSaved')); await save('/contracts/'+c.id,'PATCH',{...v,noticeDays:Number(v.noticeDays),responseHours:Number(v.responseHours),restoreHours:v.restoreHours?Number(v.restoreHours):null,visitsPerYear:Number(v.visitsPerYear)},_t('ws.contractUpdated')); }});
}

async function action(name,id){
  state.error='';
  const d=state.data, tk=state.detail?.value;
  if(name==='logout'){vision.stopAlarms();vision.reset();state.token=null;state.user=null;state.detail=null;state.page='dashboard';clearSession();return boot()}
  if(name==='back'){state.detail=null;return render()}
  if(ops.ACTIONS.includes(name))return ops.action(name,id);
  if(trace.ACTIONS.includes(name))return trace.action(name,id);
  if(vision.ACTIONS.includes(name))return vision.action(name,id);
  if(name==='ticket'||name==='equipment')return loadDetail(name,id).then(v=>{state.detail={type:name,value:v};render();window.scrollTo(0,0)}).catch(fail);
  if(name==='done'||name==='undo')return api('/checklist/'+id,'PATCH',{done:name==='done'}).then(()=>refresh()).catch(fail);
  if(name==='visitDone')return save('/visits/'+id,'PATCH',{status:'completed'},_t('ws.visitCompleted')).catch(fail);
  if(name==='approveProvider'){const p=d.providers.find(x=>x.id===id); if (p.approved&&!await confirmAction(`${_t('ws.suspend2',{name:p.name})}`,_t('ws.theyCanNoLongerBe'),{confirmLabel:_t('ws.suspend')})) return; return save(`/providers/${id}/approval`,'PATCH',{approved:!p.approved},p.approved?_t('ws.serviceProviderSuspended'):_t('ws.serviceProviderApproved')).catch(fail)}
  if(name==='userActive'){const x=d.users.find(u=>u.id===id); if (x.active&&!await confirmAction(`${_t('ws.deactivate2',{name:x.name})}`,_t('ws.theyAreSignedOutImmediately'),{confirmLabel:_t('ws.deactivate')})) return; return save('/users/'+id,'PATCH',{active:!x.active},x.active?_t('ws.userDeactivated'):_t('ws.userReactivated')).catch(fail)}
  if(name==='deviceActive'){const x=d.devices.find(v=>v.id===id); if (x.active&&!await confirmAction(`${_t('ws.deactivateDevice',{external_device_id:x.external_device_id})}`,_t('ws.readingsFromThisDeviceWill'),{confirmLabel:_t('ws.deactivate')})) return; return save('/devices/'+id,'PATCH',{active:!x.active},_t('ws.deviceUpdated')).catch(fail)}
  if(name==='runSync')return api('/integrations/sync','POST',{}).then(r=>{toast(`${_t('ws.syncAcceptedDuplicateRejected',{status:r.status,accepted:r.accepted,duplicates:r.duplicates,rejected:r.rejected})}`);return refresh()}).catch(fail);
  if(name.startsWith('fulfil:')){const p=d.parts.find(x=>x.id===id), stage=name.slice(7), needsRef=stage!=='fulfilled';return openDialog(`${label('status',stage)}: ${p.item}`,`<div class="form-grid">${field('reference',stage==='ordered'?_t('ws.purchaseOrderNumber'):stage==='shipped'?_t('ws.trackingNumberOrDeliveryNote'):_t('ws.deliveryReference'),{value:stage==='ordered'?'':p.fulfilment_reference,required:needsRef,wide:true})}</div>`,{onSubmit:async fd=>{await save(`/parts/${id}/fulfilment`,'POST',{status:stage,reference:fd.get('reference')},`${_t('ws.marked',{value:label('status',stage).toLowerCase()})}`)}})}
  if(name==='quotes')return api(`/parts/${id}/quotes`).then(q=>{const p=d.parts.find(x=>x.id===id),canDecide=is('customer_admin','plant_manager');openDialog(`${t('action.viewQuotes')}: ${p.item}`,q.length?q.map(x=>{const expired=x.valid_until&&Date.parse(x.valid_until)+86400000<=Date.now();return `<div class="quote-row"><div><b>${formatMoney(x.amount_minor,x.currency)}</b> <span class="muted">${_t('ws.leadTimeIssued',{lead_days:x.lead_days,value:t('label.days'),created_at:formatDate(x.created_at),value2:x.valid_until?` ${_t('ws.validTo',{valid_until:formatDate(x.valid_until)})}`:''})}</span></div><div class="row">${pill('status',x.status)}${expired&&x.status==='pending'?_t('ws.expired'):''}${canDecide&&x.status==='pending'&&!expired?btn(t('action.approve'),'decide:approved','primary small',x.id)+btn(t('action.reject'),'decide:rejected','secondary small',x.id):''}</div></div>`}).join(''):`<p class="muted">${t('msg.noRecords')}</p>`,{onOpen:dlg=>dlg.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>action(b.dataset.action,b.dataset.id))})}).catch(fail);
  if(name.startsWith('decide:')){const decision=name.slice(7); if (decision==='rejected'&&!await confirmAction(_t('ws.rejectThisQuotation'),_t('ws.theRequestGoesBackTo'),{confirmLabel:_t('ws.rejectQuote')})) return; closeDialog(); return save(`/quotes/${id}/decision`,'POST',{decision},decision==='approved'?_t('ws.quoteApproved'):_t('ws.quoteRejected')).catch(fail)}
  if(name==='writeGuide'){const id0=tk.id;toast(tk.guideData?.aiEnabled?_t('ws.writingTheGuideWithAi'):_t('ws.updatingTheGuide'));return api(`/tickets/${id0}/guide`,'POST',{}).then(r=>{if(state.detail?.value?.id===id0){state.detail.value.guideData=r;render()}toast(_t('ws.guideReady'))}).catch(fail)}
  if(name==='vrGuide')return openVr(tk).catch(fail);
  if(name==='uploadImage'){const e=state.detail.value;return openDialog(`${_t('ws.picture2',{value:e.asset_tag||e.model})}`,`<div class="form-grid"><div class="fld wide"><label for="f-image">${_t('ws.photoOfTheMachineJpeg2')} <span class="req">*</span></label><input id="f-image" name="file" type="file" accept="image/jpeg,image/png,image/webp" required></div></div>`,{submitLabel:_t('ws.upload'),onSubmit:async fd=>{const file=fd.get('file');if(file.size>5*1024*1024)throw Error(_t('ws.pictureExceeds5Mb'));await api(`/equipment/${e.id}/image`,'POST',{filename:file.name,mime:file.type,base64:await fileBase64(file)});toast(_t('ws.pictureSaved'));await refresh()}})}
  if(name==='removeImage'){if(!await confirmAction(_t('ws.removeThePicture'),_t('ws.theMachineShowsItsType'),{confirmLabel:_t('ws.remove')}))return;return api(`/equipment/${state.detail.value.id}/image`,'DELETE').then(()=>{toast(_t('ws.pictureRemoved'));return refresh()}).catch(fail)}
  if(name==='newTicket')return ticketForm();
  if(name==='ackAlert')return save(`/alerts/${id}/acknowledge`,'POST',{},_t('ws.alertAcknowledged')).catch(fail);
  if(name==='resolveAlert')return save(`/alerts/${id}/resolve`,'POST',{},_t('ws.alertResolved')).catch(fail);
  if(name==='alertTicket'){const a=d.alerts.find(x=>x.id===id);return ticketForm(a.equipment_id,a)}
  if(name==='oeeFor'){state.oeeFilter={range:'7d',plantId:'',equipmentId:id};state.oee=undefined;state.page='oee';state.detail=null;return render()}
  if(name==='newProduct')return productForm();
  if(name==='importEquipment')return importDialog('equipment');
  if(name==='importProducts')return importDialog('products');
  if(name==='importPlants')return importDialog('plants');
  if(name==='trend'){const [eq,param]=id.split('|');return trendDialog(eq,param).catch(fail)}
  if(name==='limits')return limitsForm(id).catch(fail);
  if(name==='explain')return explainDialog(id).catch(fail);
  if(name==='editProduct')return productForm(d.products.find(x=>x.id===id));
  if(name==='editShifts')return shiftsForm(d.plants.find(x=>x.id===id)).catch(fail);
  if(name==='newTicketHere')return ticketForm(state.detail.value.id);
  if(name==='newEquipment')return equipmentForm();
  if(name==='editEquipment')return equipmentForm(state.detail.value);
  if(name==='editEquipmentRow')return api('/equipment/'+id).then(e=>equipmentForm(e,{fromList:true})).catch(fail);
  if(name==='newContract')return contractForm();
  if(name==='addVisit'){const c=d.contracts.find(x=>x.id===id);return openDialog(`${t('action.addVisit')}: ${c.contract_number||c.title}`,`<div class="form-grid">${select('equipmentId',t('label.asset'),c.equipmentIds.map(e=>[e,assetName(e)]),{required:true})}${field('dueAt',_t('ws.dateAndTimePlantLocal'),{type:'datetime-local',required:true})}${field('notes',_t('ws.scopeOfVisit'),{wide:true})}</div>`,{onSubmit:async fd=>{await save(`/contracts/${id}/visits`,'POST',Object.fromEntries(fd),_t('ws.visitScheduled'))}})}
  if(name==='renewal')return renewalForm(d.contracts.find(x=>x.id===id));
  if(name==='editVisit'){const c=d.contracts.find(x=>x.visits.some(v=>v.id===id));return visitForm(c,c.visits.find(v=>v.id===id));}
  if(name==='newCompany')return companyForm();
  if(name==='editCompany')return companyForm(d.companies.find(x=>x.id===id));
  if(name==='newPlant')return plantForm();
  if(name==='editPlant')return plantForm(d.plants.find(x=>x.id===id));
  if(name==='newUser')return userForm();
  if(name==='editUser')return userEditForm(d.users.find(x=>x.id===id));
  if(name==='newProvider')return providerForm();
  if(name==='editProvider')return providerForm(d.providers.find(x=>x.id===id));
  if(name==='userDuties'){const x=d.users.find(v=>v.id===id),cur=parseList(x.vision_duties);return openDialog(`${_t('ws.visionDuties2',{name:x.name})}`,`<div class="form-grid">${checkboxes('duties',_t('ws.responsibleFor'),[['ehs',_t('ws.ehsOfficerPpeComplianceAnd')],['security',_t('ws.securityFacilityAdminRestrictedArea')],['qa',_t('ws.qaLeadQualityInspectionAnd')]],{values:cur})}<p class="muted wide">${_t('ws.decidesWhichVisionAlarmsAppear')}</p></div>`,{onSubmit:async fd=>{await save('/users/'+id,'PATCH',{visionDuties:fd.getAll('duties')},_t('ws.visionDutiesSaved'))}})}
  if(name==='resetPassword'){const x=d.users.find(v=>v.id===id);return openDialog(`${t('action.resetPassword')}: ${x.name}`,`<div class="form-grid">${field('newPassword',_t('ws.newTemporaryPassword'),{required:true,minlength:12,autocomplete:'off',wide:true,help:`${_t('ws.isSignedOutOnAll',{name:x.name})}`})}</div>`,{submitLabel:_t('ws.resetPassword'),onSubmit:async fd=>{await save(`/users/${id}/password`,'POST',{newPassword:fd.get('newPassword')},t('msg.passwordReset'))}})}
  if(name==='newArea')return openDialog(_t('ws.addServiceArea'),`<div class="form-grid">${field('code',_t('ws.code'),{required:true,maxlength:20,help:_t('ws.shortAndStableEG'),autocapitalize:'characters'})}${field('name',_t('ws.name'),{required:true,help:_t('ws.eGIndiaSouth')})}</div>`,{onSubmit:async fd=>{await save('/service-areas','POST',Object.fromEntries(fd),_t('ws.serviceAreaAdded'))}});
  if(name==='renameArea'){const a=d.serviceAreas.find(x=>x.code===id);return openDialog(`${_t('ws.rename',{code:a.code})}`,`<div class="form-grid">${field('name',_t('ws.name'),{value:a.name,required:true,wide:true,help:_t('ws.theCodeStaysTheSame')})}</div>`,{onSubmit:async fd=>{await save(`/service-areas/${encodeURIComponent(a.code)}`,'PATCH',{name:fd.get('name')},_t('ws.serviceAreaRenamed'))}})}
  if(name==='addCode'){const title={failureCategories:_t('ws.failureCategories'),failureModes:_t('ws.failureModes'),rootCauses:_t('ws.rootCauses'),actions:_t('ws.maintenanceActions')}[id];return openDialog(`${_t('ws.addTo',{title:title})}`,`<div class="form-grid">${field('label',_t('ws.name'),{required:true,maxlength:60,wide:true,help:_t('ws.eGLubricationItIs')})}</div>`,{submitLabel:_t('ws.add2'),onSubmit:async fd=>{const r=await api(`/settings/codes/${id}`,'POST',{label:fd.get('label')});state.cat=null;toast(`${_t('ws.added',{code:humanise(r.code)})}`);await refresh()}})}
  if(name==='deleteCode'){const [list,code]=id.split('|');if(!await confirmAction(`${_t('ws.delete3',{code:humanise(code)})}`,_t('ws.itIsNoLongerOffered'),{confirmLabel:_t('ws.delete')}))return;return api(`/settings/codes/${list}/${encodeURIComponent(code)}`,'DELETE').then(async r=>{state.cat=null;toast(r.ticketsKeepingCode?`${_t('ws.deletedTicketSKeepThis',{ticketsKeepingCode:r.ticketsKeepingCode})}`:_t('ws.deleted'));await refresh()}).catch(fail)}
  if(name==='editChecklist')return openDialog(`${_t('ws.standardChecklist',{value:label('machine',id)})}`,`<div class="form-grid">${field('items',_t('ws.checklistItems'),{type:'textarea',value:(d.checklists[id]||[]).join('\n'),required:true,wide:true,rows:12,help:_t('ws.oneItemPerLineIn')})}</div>`,{onSubmit:async fd=>{await save(`/settings/checklists/${id}`,'PATCH',{items:String(fd.get('items')).split('\n').map(s=>s.trim()).filter(Boolean)},_t('ws.checklistSaved'))}});
  if(name==='status')return statusForm(tk);
  if(name==='assign')return api(`/tickets/${tk.id}/candidates`).then(list=>{const ok=list.filter(c=>c.eligible),no=list.filter(c=>!c.eligible);openDialog(t('action.assign'),`<div class="form-grid">${ok.length?select('assignee',_t('ws.engineerOrServiceProvider'),ok.map(c=>[`${c.type}:${c.id}`,`${_t('ws.openJobs',{value:c.type==='engineer'?_t('ws.engineer'):_t('ws.provider'),name:c.name,openWork:c.openWork})}`]),{required:true,wide:true,help:_t('ws.onlyThoseCoveringThisPlant')}):_t('ws.noEligibleEngineerOrService')}${no.length?`<div class="wide mini">${_t('ws.notEligible',{value:no.map(c=>`${esc(c.name)} (${esc(c.reasons.join(', '))})`).join('; ')})}</div>`:''}</div>`,{submitLabel:_t('ws.assign'),onSubmit:ok.length?async fd=>{const [assigneeType,assigneeId]=String(fd.get('assignee')).split(':');await save(`/tickets/${tk.id}/assign`,'POST',{assigneeType,assigneeId},_t('ws.assigned'))}:undefined})}).catch(fail);
  if(name==='checklist')return openDialog(t('action.checklist'),`<div class="form-grid">${field('item',_t('ws.inspectionItem'),{required:true,wide:true})}${field('note',t('label.note'),{wide:true})}</div>`,{onSubmit:async fd=>{await save(`/tickets/${tk.id}/checklist`,'POST',Object.fromEntries(fd))}});
  if(name==='workLog')return openDialog(t('action.logWork'),`<div class="form-grid">${field('description',_t('ws.workPerformed'),{type:'textarea',required:true,wide:true})}${field('minutes',_t('ws.timeSpent'),{type:'number',required:true,unit:'min',min:1,max:10080})}${field('partsUsed',_t('ws.partsUsed'),{help:_t('ws.partNumbersAndQuantities')})}</div>`,{onSubmit:async fd=>{const v=Object.fromEntries(fd);await save(`/tickets/${tk.id}/work-logs`,'POST',{...v,minutes:Number(v.minutes)},_t('ws.workLogged'))}});
  if(name==='part')return openDialog(t('action.requestPart'),`<div class="form-grid">${field('partNumber',_t('ws.partNumber'),{required:true,help:_t('ws.manufacturerOrCatalogueNumber')})}${field('manufacturer',_t('ws.manufacturer'))}${field('item',_t('ws.description'),{required:true,wide:true})}${field('quantity',_t('ws.quantity'),{type:'number',value:1,required:true,min:1})}${select('unit',_t('ws.unit'),options(state.cat?.partUnits||[]),{value:'pcs',required:true})}${select('urgency',_t('ws.urgency'),options(state.cat?.partUrgency||[]),{value:'normal',required:true,help:_t('ws.breakdownMachineIsStoppedWaiting')})}</div>`,{onSubmit:async fd=>{const v=Object.fromEntries(fd);await save(`/tickets/${tk.id}/parts`,'POST',{...v,quantity:Number(v.quantity)},_t('ws.partRequested'))}});
  if(name==='signoff'){if(customer())return openDialog(t('action.signoff'),`<div class="form-grid">${field('signerName',t('label.signerName'),{value:state.user.name,required:true,wide:true})}</div>`,{submitLabel:_t('ws.signOff'),onSubmit:async fd=>{await save(`/tickets/${tk.id}/signoff`,'POST',{signerName:fd.get('signerName')},_t('ws.signedOff'))}});
    let pad;return openDialog(t('action.signoff'),`<div class="form-grid">${field('signerName',t('label.signerName'),{required:true,wide:true})}<div class="wide"><label>${t('label.signature')} <span class="req">*</span></label><canvas class="signature" id="sig"></canvas><button type="button" class="secondary small" id="clear-sig">${t('action.clear')}</button></div></div>`,{submitLabel:_t('ws.signOff'),onOpen:dlg=>{pad=signaturePad(dlg.querySelector('#sig'));dlg.querySelector('#clear-sig').onclick=()=>pad.clear()},onSubmit:async fd=>{if(pad.isEmpty())throw Error(t('msg.signFirst'));await save(`/tickets/${tk.id}/signoff`,'POST',{signerName:fd.get('signerName'),signatureBase64:pad.toBase64()},_t('ws.signedOff'))}})}
  if(name==='quote'){const p=d.parts.find(x=>x.id===id),code=companyOf(p.company_id)?.currency||prefs().currency;return openDialog(`${t('action.quote')}: ${p.item}`,`<div class="form-grid">${field('amount',_t('ws.totalPrice'),{type:'number',required:true,min:0.01,step:0.01,unit:code})}${select('currency',_t('ws.currency'),currencies().map(x=>[x,x]),{value:code,required:true})}${field('leadDays',_t('ws.leadTime'),{type:'number',value:3,required:true,unit:'days',min:0,max:365})}${field('validUntil',_t('ws.quoteValidUntil'),{type:'date',value:today(30),required:true,min:today()})}</div>`,{submitLabel:_t('ws.sendQuote'),onSubmit:async fd=>{const v=Object.fromEntries(fd);await save(`/parts/${id}/quote`,'POST',{amountMinor:toMinorUnits(v.amount,v.currency),currency:v.currency,leadDays:Number(v.leadDays),validUntil:v.validUntil},_t('ws.quoteSent'))}})}
  if(name==='attachment')return openDialog(t('action.attach'),`<div class="form-grid">${select('kind',_t('ws.type'),(state.detail.type==='equipment'?['manual','photo']:['photo','evidence']).map(x=>[x,humanise(x)]),{required:true})}<div class="fld wide"><label for="f-file">${_t('ws.pdfOrImageMax5')} <span class="req">*</span></label><input id="f-file" name="file" type="file" accept=".pdf,image/png,image/jpeg,image/webp" required></div></div>`,{submitLabel:_t('ws.upload'),onSubmit:async fd=>{const file=fd.get('file');if(file.size>5*1024*1024)throw Error(_t('ws.fileExceeds5Mb'));await save('/attachments','POST',{entityType:state.detail.type,entityId:state.detail.value.id,kind:fd.get('kind'),filename:file.name,mime:file.type,base64:await fileBase64(file)},_t('ws.fileUploaded'))}});
  if(name==='editDevice')return deviceForm(d.devices.find(x=>x.id===id));
  if(name==='mapDevice')return openDialog(_t('ws.mapIotDeviceToThis'),`<div class="form-grid">${field('externalDeviceId',_t('ws.externalDeviceId'),{required:true,help:_t('ws.asUsedByTheMachine')})}${field('staleAfterMinutes',_t('ws.markStaleAfter'),{type:'number',value:30,unit:'min',min:1,max:10080,required:true})}</div>`,{onSubmit:async fd=>{await save('/devices','POST',{externalDeviceId:fd.get('externalDeviceId'),equipmentId:state.detail.value.id,staleAfterMinutes:Number(fd.get('staleAfterMinutes'))},_t('ws.deviceMapped'))}});
}
// Forms that live on a page rather than in a dialog (account password, default response targets).
function bindInlineForms(){
  document.querySelectorAll('form[data-inline]').forEach(f=>f.onsubmit=async e=>{e.preventDefault();const v=Object.fromEntries(new FormData(f));try{
    if(f.dataset.inline==='password'){const r=await api('/me/password','POST',v);saveSession(r.token);state.token=r.token;state.user=r.user;f.reset();toast(t('msg.passwordChanged'));render();}
    if(f.dataset.inline==='scan'){const r=await api('/settings/scan-policy','PATCH',v);if(state.cat)state.cat.scanPolicy=r;toast(_t('ws.scanPolicySaved'));render();}
    if(f.dataset.inline==='targets'){await save('/settings/response-targets','PATCH',Object.fromEntries(Object.entries(v).map(([k,x])=>[k,Number(x)])),_t('ws.responseTargetsSaved'));}
  }catch(err){toast(err.message,'error')}});
}
// A ticket's detail also carries its assistant conversation and repair guide.
async function loadDetail(type,id){ if (type==='equipment') return api('/equipment/'+id); const [t,assistantData,guideData]=await Promise.all([api('/tickets/'+id),api(`/tickets/${id}/assistant`).catch(()=>null),api(`/tickets/${id}/guide`).catch(()=>null)]); return {...t,assistantData,guideData}; }
async function refresh(){if(state.detail)state.detail.value=await loadDetail(state.detail.type,state.detail.value.id).catch(()=>{state.detail=null});await load();}
const fileBase64=file=>new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(file)});
document.addEventListener('click',async e=>{const a=e.target.closest('[data-download]');if(!a)return;e.preventDefault();try{const r=await fetch(a.href,{headers:{authorization:`Bearer ${state.token}`}});if(!r.ok)throw Error(_t('ws.unableToDownload'));const url=URL.createObjectURL(await r.blob()),link=document.createElement('a');link.href=url;link.download=a.textContent;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(err){toast(err.message,'error')}});
const trace=createTrace({state,api,render,fail,when,header,factoryManager,admin:()=>admin(),customer:()=>customer()});
const vision=createVision({state,api,render,fail,when,header,is,customer:()=>customer(),admin:()=>admin(),raiseTicket:(equipmentId,prefill)=>ticketForm(equipmentId,null,prefill)});
const ops=createOps({state,api,save,render,fail,when,assetName,header,RANGES,pctText,since,factoryManager,admin,is,customer,t,refresh,action});
boot();
